// Exact OPFS keys generated by the removed Wllama runtime for TIRTA's pinned
// model URL: SHA-1(url) + '_' + filename; metadata uses '__metadata__' prefix.
// Never delete the shared 'cache' directory, other files, IndexedDB or SW caches.
export const retiredModelKey = 'ce940091cef2f16c6ca7d17c78e7b2156976bbbc_Qwen_Qwen3-0.6B-Q4_K_M.gguf';
export async function discardRetiredModelCache(storage = navigator.storage) {
  try {
    const root = await storage.getDirectory();
    const cache = await root.getDirectoryHandle('cache', { create: false });
    await Promise.all([retiredModelKey, `__metadata__${retiredModelKey}`].map(async key => {
      try { await cache.removeEntry(key); } catch { /* Absent or locked files do not block the app. */ }
    }));
  } catch { /* OPFS may be unavailable; no project storage is accessed. */ }
}
